    static final String RESET = "\u001B[0m";
    static final String GREEN = "\u001B[32m";
    static final String YELLOW = "\u001B[33m";

    public static void main(String[] args) {
        // The title screen.
        System.out.println("=======================");
        System.out.println("     FIVE  LETTERS");
        System.out.println("=======================");
